import{_ as r,o as l,c as n,j as e,a}from"./chunks/framework.scx6l_IK.js";const f=JSON.parse('{"title":"答疑2014-箩筐与大海","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/答疑2014-箩筐与大海.md","filePath":"60-原文段落/答疑2014-箩筐与大海.md","lastUpdated":1778155802000}'),o={name:"60-原文段落/答疑2014-箩筐与大海.md"};function s(_,t,c,d,p,i){return l(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"答疑2014-箩筐与大海",tabindex:"-1"},[a("答疑2014-箩筐与大海 "),e("a",{class:"header-anchor",href:"#答疑2014-箩筐与大海","aria-label":'Permalink to "答疑2014-箩筐与大海"'},"​")],-1),e("blockquote",null,[e("p",null,[a("来源："),e("a",{href:"/01-Raw-Sources/03_答疑专辑2014_佛道"},"03_答疑专辑2014_佛道"),a(" 原章节：佛菩萨与我们身上的能量哪里来的 切分日期：2026-05-06")])],-1),e("hr",null,null,-1),e("p",null,"师兄：师父好，佛祖身上的能量是自身本来具有的，还是宇宙中的能量在佛祖身上的体现？每个人身上的气感光感等等是宇宙中能量穿透身体的表现吗？感恩师父！",-1),e("p",null,'了空居士：你正好问到佛祖，这是一个特殊的人物。释迦牟尼佛在《妙法莲华经》如来寿量品里告诉我们，他久远劫来就圆满成佛了。那么他今生来到娑婆世界示现圆满成佛，他是来示现一下，也就是他回忆一下就圆满了。他投胎以后，仿佛记得不是那么清楚，他安静下来就又想起来了。严格来说，佛祖这个人他投胎的时候，本来就有大智慧、高能量的。他的能量就是和自性相应而获得整个法界的能量体。就好像你把一个箩筐扔到大海里，箩筐里面的水，外面的水，其实是一个整体。我们这些普通的人与生俱来也是有能量的。我们的能量级比较低，因为种种执着智慧也不圆满。我们修炼的过程，就是破尽种种执着，使我们和整个大自然的能量融通而已。这是释迦牟尼佛在菩提树下说的，"奇哉！奇哉！一切众生皆具如来智慧德相，只因妄想执著不能证得，若离妄想，则无师智、无碍智、自然智自然现前。" 我在这里答疑解惑，其实也是帮大家破迷，一破迷，你们就言下大悟，言下大悟之后，你们就升起一种恭敬心，刹那间就可能跟我的能量场就融通了。所以我常常劝大家，有时间多来现场，听我说话。过后，相对来说会差一些。一跟我相应，你们就进入一个层次了。那我的能量从哪里来？我能量从跟我师父相应而来；那我的师傅能量从哪里来？从跟他的师父乃至一切圣贤相应而来。我修的时间长了，也会和我的师傅乃至一切圣贤相应。所以修炼说到最根本处就是见贤思齐，正心修身。谢谢大家。',-1)])])}const m=r(o,[["render",s]]);export{f as __pageData,m as default};
